head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05040";
scwin.feeCalcDiv = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.feeCalcDiv = $c.util.getComponent('feeCalcDiv');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05040.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_feeCalcSample_onclick
 * @description 「양식 다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_feeCalcSample_onclick = function(e){
    try {
        scwin.feeCalcSample()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05040.btn_feeCalcSample_onclick' }); }
};

/**
 * @method
 * @name btn_feeCalcUploadPop_onclick
 * @description 「파일 업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_feeCalcUploadPop_onclick = async function(e){
    try {
        await scwin.feeCalcUploadPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05040.btn_feeCalcUploadPop_onclick' }); }
};

/**
 * @method
 * @name btn_rules_onclick
 * @description 「계산원칙」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rules_onclick = function(e){
    try {
        scwin.rules()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05040.btn_rules_onclick' }); }
};

/**
 * @method
 * @name btn_reset_onclick
 * @description 「초기화」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reset_onclick = async function(e){
    try {
        await scwin.reset()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05040.btn_reset_onclick' }); }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 「엑셀 저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excel_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05040.btn_excel_onclick' }); }
};

/**
 * @method
 * @name btn_print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_print_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05040.btn_print_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_excel
 * @description excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excel = async function () {
    const sbmOptions = {
        id: "tx_fn_excel",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_excelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/list/elwPage.do?method=elwFeeCalcExcelPrint", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name rules
 * @description rules 처리
 * @returns {void}
 * @hidden N
 */
scwin.rules = function () {
    (Promise.resolve($c.win.openPopup("/jldfil35709/jldfil35709.xml", { id: "elwCalRule", scrollbars: false, resizable: false, width: "570", height: "540", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("elwCalRule"); this.closed = true; } });
};

/**
 * @method
 * @name feeCalcSample
 * @description fee Calc Sample 처리
 * @returns {void}
 * @hidden N
 */
scwin.feeCalcSample = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil05011/jldfil05011.xml');
};

/**
 * @method
 * @name feeCalcUploadPop
 * @description fee Calc Upload Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.feeCalcUploadPop = async function () {
    await $c.win.openPopup('/jldfil05011/jldfil05011.xml', { id: "elwExcelUploadPop", scrollbars: false, resizable: true, width: "610", height: "700", type: "pageFramePopup" }, { method: "elwFeeCalcUploadPop" });
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        frm.action = '/list/elwPage.do';
        $c.util.getComponent('dma_excelReq').set('method', 'elwFeeCalcExcelDownload');
        await scwin.tx_fn_excel();
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    const frm = (document.searchForm || { elements: [] });
    const popNm = "elwFeeCalcPrint";
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        $c.win.openPopup("", String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof popNm !== 'undefined' ? popNm : '') ? Object.assign({ id: "elwFeeCalcPrint", scrollbars: true, resizable: true, width: "880", height: "600", type: "pageFramePopup" }, { id: (typeof popNm !== 'undefined' ? popNm : '') }) : { id: "elwFeeCalcPrint", scrollbars: true, resizable: true, width: "880", height: "600", type: "pageFramePopup" }), {});
        frm.target = popNm;
        frm.action = "/list/elwPage.do?method=elwFeeCalcExcelPrint";
        await scwin.tx_fn_print();
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reset = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        $c.util.getComponent('dma_excelReq').set('rsltFlag', "N");
        $c.util.getComponent("ipt_totFee").setValue("");
        ($c.util.getComponent("txt_feeCalcDivData") && $c.util.getComponent("txt_feeCalcDivData").setValue) ? $c.util.getComponent("txt_feeCalcDivData").setValue("") : (($c.util.getComponent("txt_feeCalcDivData") && $c.util.getComponent("txt_feeCalcDivData").setText) ? $c.util.getComponent("txt_feeCalcDivData").setText("") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_feeCalcDivData"), void ("")));
        $c.util.getComponent('txt_feeCalcDivData').setStyle("display", "none");
        scwin.feeCalcDiv.setStyle("display", "");
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
};

/**
 * @method
 * @name setFeeCalcRslt
 * @description set Fee Calc Rslt 처리
 * @param {*} pDataArr pDataArr
 * @param {*} pIsuTotFee pIsuTotFee
 * @returns {void}
 * @hidden N
 */
scwin.setFeeCalcRslt = function (pDataArr, pIsuTotFee) {
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_excelReq').set('rsltFlag', "Y");
    let txt = "<table style=\"width:760px;\" class=\"table_board_default\" title=\"ELW 상장수수료 계산기 - 목록\" >";
    txt += "<colgroup>                               ";
    txt += "	<col width=\"60px\" />                 ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "</colgroup>                              ";
    txt += "<thead>                                  ";
    txt += "	<tr>                                   ";
    txt += "		<th class=\"subject\">번호</th>        ";
    txt += "		<th class=\"subject\">종목약명</th>      ";
    txt += "		<th class=\"subject\">발행수량</th>      ";
    txt += "		<th class=\"subject\">발행가액</th>      ";
    txt += "		<th class=\"subject\">발행총액</th>      ";
    txt += "		<th class=\"subject\">수수료</th>       ";
    txt += "	</tr>                                  ";
    for (let i = 0; i < pDataArr.length; i++) {
        txt += "<tr>";
        txt += "	<td id='tdNum' class='inputLeft_alignCenter' width='50'>" + (i + 1) + "</td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuAbbrv' class='form_search_no_border' readonly='readonly' size='40' value='" + pDataArr[i].isu_abbrv + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuQty' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_qty + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuPrc' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_prc + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuTotamt' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_totamt + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuFee' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_fee + "'/></td>";
        txt += "</tr>";
    }
    const dataDiv = $c.util.getComponent("txt_feeCalcDivData");
    dataDiv.setStyle('width', "780px");
    dataDiv.setStyle('height', "320px");
    dataDiv.innerHTML = txt;
    scwin.feeCalcDiv.setStyle("display", "none");
    $c.util.getComponent('txt_feeCalcDivData').setStyle("display", "");
    $c.util.getComponent("ipt_totFee").setValue(pIsuTotFee);
    setTimeout(function() {
            $c.util.getComponent("dialogLoading").setStyle("display", "none");
        }, 800);
};

/**
 * @method
 * @name numFormat
 * @description num Format 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.numFormat = async function (obj) {
    if ((obj.getValue() == null ? '' : String(obj.getValue())) !== '' && !scwin.isMinusNumber(obj.getValue())) {
        obj.setValue("");
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
        return;
    }
    if (isNaN(obj.getValue())) {
        obj.setValue("");
        return;
    }
    if (Number(obj.getValue()) > 999999999999999 || Number(obj.getValue()) < -999999999999999) {
        obj.setValue("");
        await $c.win.alert("입력한 숫자가 범위를 초과하였습니다.");
        obj.focus();
        return;
    }
    let str = Number(obj.getValue()) + "";
    let sMinusChar = "";
    if (Number(obj.getValue()) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let tempStr = str;
    let fltStr = "";
    if (str.indexOf(".") > -1) {
        tempStr = str.substr(0, str.indexOf("."));
        fltStr = str.substr(str.indexOf("."));
    }
    const leng = tempStr.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.setValue(Number(obj.getValue()));
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + tempStr.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.setValue(sMinusChar + result.substring(1) + fltStr);
        } else {
            obj.setValue(sMinusChar + str.substr(0, pos) + result + fltStr);
        }
    }
    return;
};

/**
 * @method
 * @name isMinusNumber
 * @description 음수를 포함한 숫자 문자열인지(as-is 공통 isMinusNum — 첫 글자 숫자·'-'·'.', 나머지 숫자·'.')
 * @param {*} value 문자열
 * @returns {Boolean}
 * @hidden N
 */
scwin.isMinusNumber = function (value) {
    return /^[-0-9.][0-9.]*$/.test(String(value ?? ""));
};
